INSERT INTO `advice_record` (`advice_id`, `user_id`, `advice_type`, `advice_content`, `advice_source`, `advice_date`, `created_at`) VALUES (100001, 10001, '运动', '建议将有氧与力量训练结合，保持每周至少5天活动频率。', 'AI', '2026-03-17', '2026-03-17 09:30:00');
INSERT INTO `advice_record` (`advice_id`, `user_id`, `advice_type`, `advice_content`, `advice_source`, `advice_date`, `created_at`) VALUES (100002, 10001, '饮食', '晚餐主食可适当减少，优先补充优质蛋白和蔬菜。', '规则', '2026-03-17', '2026-03-17 09:40:00');
INSERT INTO `advice_record` (`advice_id`, `user_id`, `advice_type`, `advice_content`, `advice_source`, `advice_date`, `created_at`) VALUES (100003, 10002, '阶段分析', '目前体重维持较稳定，建议继续控制精制糖摄入并增加步行。', '混合', '2026-03-17', '2026-03-17 10:00:00');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139001, 10003, 'assistant', '今日开场', '我已经同步了你的身体档案、今日饮食、训练和趋势数据。今天整体节奏不错：热量接近目标、蛋白质充足，训练也已经启动，接下来重点是补水和晚间恢复。', '2026-05-28 08:10:00');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139002, 10003, 'user', '饮食咨询', '今天晚餐还需要注意什么？', '2026-05-28 12:30:00');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139003, 10003, 'assistant', '晚餐建议', '午餐和加餐已经把蛋白质打得比较稳，晚餐建议保持清淡：一份鱼肉或豆腐、一拳头杂粮饭、两拳头蔬菜。这样既能补足营养，也不会让全天热量明显超标。', '2026-05-28 12:31:00');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139004, 10003, 'user', '训练咨询', '今天早上练了核心，晚上还要运动吗？', '2026-05-28 16:20:00');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139005, 10003, 'assistant', '训练建议', '早上的核心训练已经很好，晚上不需要再做高强度训练。更推荐 15-20 分钟轻松散步或拉伸，把久坐后的紧张感放下来，也有助于睡前恢复。', '2026-05-28 16:21:00');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139006, 10003, 'user', '恢复咨询', '今晚怎样更容易早睡？', '2026-05-27 21:00:00');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139007, 10003, 'assistant', '睡眠建议', '建议把睡前 40 分钟留给固定流程：关掉高刺激内容、补最后一小杯水、做 5 分钟拉伸或呼吸练习。目标不是一下子完美早睡，而是把入睡时间稳定提前 15 分钟。', '2026-05-27 21:01:00');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139008, 10003, 'user', '综合平衡', '睡前有点焦虑怎么办？', '2026-05-28 17:33:05');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139009, 10003, 'assistant', '睡眠建议', '睡前有焦虑感是很正常的，尤其在思考比较多的时候。我们可以通过一些小方法来帮助大脑“降温”，让它知道现在是放松休息的时间了。比如，你可以试试在睡前 30-60 分钟做一些轻柔的拉伸，或者进行 5-10 分钟的腹式呼吸练习。如果脑子里有很多想法停不下来，也可以尝试在睡前一两个小时把它们写下来，暂时清空大脑，这样就不用带着这些思绪上床了。关键是找到适合你的放松方式，让睡前成为一个平静的过渡期。', '2026-05-28 17:33:28');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139010, 10003, 'user', '综合平衡', '如果我想用体态照追踪变化，你建议我怎么拍？', '2026-05-28 17:59:17');
INSERT INTO `assistant_chat_message` (`message_id`, `user_id`, `role`, `tag`, `content`, `created_at`) VALUES (139011, 10003, 'assistant', '体态追踪', '好的，体态照是追踪身体变化非常直观有效的方式！为了确保每次都能拍出有对比价值的照片，我建议你注意以下几点：\n\n1.  **固定时间：** 选择每周或每两周的同一天、同一时间（比如早上起床后、空腹时），身体状态最稳定。\n2.  **固定光线：** 在同一个地方，确保光线充足且均匀，避免逆光或强烈的阴影。\n3.  **固定背景：** 选择一面纯色墙壁作为背景，避免杂物干扰视线。\n4.  **固定服装：** 穿着贴身、暴露身体线条的衣物（如运动内衣、短裤），或者只穿内衣，这样能更清晰地看到身体轮廓和肌肉变化。\n5.  **固定姿势：** 至少拍三张：正面、侧面（侧身完全对准镜头）、背面。可以尝试放松站立和收腹站立两种状态，双手自然下垂或叉腰，脚跟并拢。\n6.  **固定距离和角度：** 将手机或相机固定在三脚架上，或请同一位朋友帮忙拍摄，确保每次拍摄的距离和高度一致。\n7.  **记录：** 拍完后可以在手机里建一个相册专门存放这些照片，并标记日期，方便对比。\n\n这样坚持下来，你会发现身体的微小变化，这些视觉反馈会给你很大的动力！', '2026-05-28 17:59:47');
