INSERT INTO `assistant_plan_snapshot` (`snapshot_id`, `user_id`, `focus`, `title`, `summary`, `readiness_score`, `risk_label`, `next_check_in`, `quick_questions_json`, `metrics_json`, `priorities_json`, `insights_json`, `actions_json`, `reminders_json`, `generated_at`, `created_at`, `derived_contents_json`, `modality_ideas_json`) VALUES (129002, 10003, '综合平衡', '今日健康面板', '你今天的健康节奏整体良好，蛋白质摄入充足，周训练目标已达成。当前重点是补充水分，并利用睡前恢复提升睡眠质量，助力体重目标稳步前进。', 93, '良好，关注恢复', '明天早上 08:00', '如何让今晚睡得更好？', '有哪些健康的晚餐搭配？', '明天训练怎么安排比较好？', '下午想喝奶茶时有什么替代方案？', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '睡前 40 分钟，记得开始你的放松流程哦。', '今晚别忘了补充剩余的 320ml 水分。', '如果可以，晚上去散散步或做做拉伸，放松一下吧。', '2026-05-28 17:26:55', '2026-05-28 17:26:55', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]');
