INSERT INTO `assistant_plan_snapshot` (`snapshot_id`, `user_id`, `focus`, `title`, `summary`, `readiness_score`, `risk_label`, `next_check_in`, `quick_questions_json`, `metrics_json`, `priorities_json`, `insights_json`, `actions_json`, `reminders_json`, `generated_at`, `created_at`, `derived_contents_json`, `modality_ideas_json`) VALUES (129004, 10003, '综合平衡', '保持节奏，细致观察身体变化', '你今天整体节奏稳健，蛋白质和训练都达标，体重也稳步下降。恢复端仍需关注。很高兴你开始关注体态照，这是一个非常直观有效的追踪方式。建议继续保持良好习惯，并通过体态照更清晰地记录和感受身体的变化。', 93, '低风险', '明日早餐前', '你今天晚餐计划吃什么？', '今天睡前打算如何放松？', '有没有特别想了解的身体数据？', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '今晚记得补充水分哦！', '睡前给自己留出放松时间，放下手机，做做拉伸或呼吸练习。', '2026-05-28 17:59:19', '2026-05-28 17:59:19', '[object Object]', '[object Object]', '[object Object]');
INSERT INTO `assistant_plan_snapshot` (`snapshot_id`, `user_id`, `focus`, `title`, `summary`, `readiness_score`, `risk_label`, `next_check_in`, `quick_questions_json`, `metrics_json`, `priorities_json`, `insights_json`, `actions_json`, `reminders_json`, `generated_at`, `created_at`, `derived_contents_json`, `modality_ideas_json`) VALUES (129005, 10003, '综合平衡', '你好，今天我们继续优化综合平衡！', '你最近在体重管理和运动习惯上做得非常棒，基础活动量很扎实，这为你的健康打下了坚实基础。当前，我们需要重点关注的是睡眠恢复和每日饮水，以及如何更好地管理睡前焦虑，帮助你达到更全面的身心平衡。', 56, '中等关注', '明天早上', '昨晚的睡眠质量如何？睡前焦虑感有缓解吗？', '今天你的饮水情况怎么样了？', '晚餐是否按照清淡的建议搭配了呢？', '今天除了早上的核心训练，还有做其他放松活动吗？', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '睡前 30 分钟进行放松练习，帮助缓解焦虑。', '今天剩余时间请分多次补充水分，目标 1920ml。', '晚餐清淡搭配，保证足量蛋白质摄入。', '2026-06-01 11:52:48', '2026-06-01 11:52:48', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]', '[object Object]');
